'use strict';

/**
 * Documents page: lists the generated PDFs (from public/docs/index.json) with
 * view + download actions. Each document is real — generated by
 * scripts/generate-docs.js from the same database the site uses.
 */

(function () {
  if (typeof document === 'undefined' || typeof window === 'undefined') return;
  const App = window.App;

  const PDF_ICON = '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z"/><path d="M14 2v6h6"/><path d="M9 13h1.5a1.5 1.5 0 0 1 0 3H9zM9 13v6"/></svg>';

  function card({ title, subtitle, file }) {
    return `
      <article class="doc-card reveal is-in">
        <div class="doc-icon">${PDF_ICON}</div>
        <div style="flex:1">
          <h3>${App.escapeHtml(title)}</h3>
          <p>${App.escapeHtml(subtitle || 'PDF document')}</p>
          <div class="doc-actions">
            <a class="btn btn--primary btn--sm" href="${App.escapeHtml(file)}" download>Download</a>
            <a class="btn btn--ghost btn--sm" href="${App.escapeHtml(file)}" target="_blank" rel="noopener">View</a>
          </div>
        </div>
      </article>`;
  }

  function render(container, items) {
    if (!container) return;
    container.classList.add('stagger');
    container.innerHTML = items.length
      ? items.map(card).join('')
      : '<div class="empty">No documents available.</div>';
  }

  document.addEventListener('DOMContentLoaded', async () => {
    await App.creditsReady();
    try {
      const index = await App.api('/docs/index.json');
      render(document.getElementById('doc-brochure'),
        (index.brochures || []).map((b) => ({ title: b.title, subtitle: 'Company profile & services', file: b.file })));
      render(document.getElementById('doc-itineraries'),
        (index.itineraries || []).map((i) => ({ title: i.title, subtitle: 'Full tour itinerary', file: i.file })));
      render(document.getElementById('doc-visas'),
        (index.visaChecklists || []).map((v) => ({ title: v.label + ' Visa', subtitle: v.region + ' — document checklist', file: v.file })));
    } catch (err) {
      ['doc-brochure', 'doc-itineraries', 'doc-visas'].forEach((id) =>
        App.showEmpty(document.getElementById(id), 'Could not load documents.'));
      App.toast(err.message, 'err');
    }
  });
})();
